  });
  profile.settings.file = settingsFile
    ? canonicalPath(settingsFile, profile.workspace.cwd)
    : null;
  profile.mcp.configFile = mcpConfig
    ? canonicalPath(mcpConfig, profile.workspace.cwd)
    : null;
  profile.plugins.bundle = bundle
